def luhn_valid(s):
    s = s.replace(" ", "").strip()
    if len(s) < 2:
        return False
    total = 0
    for i in range(len(s)-1, -1, -2):
        digit = int(s[i])
        if digit >= 5:
            digit -= 9
        total += digit
    for i in range(len(s)-2, -1, -2):
        digit = int(s[i]) * 2
        if digit >= 10:
            digit -= 9
        total += digit
    return total % 10 == 0
```

